1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import { upsertSidebarOrderPreferenceSchema } from "@paperclipai/shared";
4	import { forbidden, unauthorized } from "../errors.js";
5	import { logActivity, sidebarPreferenceService } from "../services/index.js";
6	import { expressHandler } from "../http/express-adapter.js";
7	import type { Handler, RequestCtx } from "../http/types.js";
8	import type { StorageService } from "../storage/types.js";
9	
10	/** Asserts board actor with a userId and returns the userId. */
11	function requireBoardUserIdCtx(ctx: RequestCtx): string {
12	  if (ctx.actor?.type !== "board") {
13	    throw forbidden("Board access required");
14	  }
15	  if (!ctx.actor.userId) {
16	    throw forbidden("Board user context required");
17	  }
18	  return ctx.actor.userId;
19	}
20	
21	/** Minimal company access check using fields available on ActorContext. */
22	function assertCompanyAccessCtx(ctx: RequestCtx, companyId: string) {
23	  if (!ctx.actor) throw unauthorized();
24	  if (ctx.actor.type === "agent" && ctx.actor.companyId !== companyId) {
25	    throw forbidden("Agent key cannot access another company");
26	  }
27	  // Board actor company-list enforcement is handled by the Express auth
28	  // middleware before the Handler is reached.
29	  // TODO(cloudflare): re-enforce companyIds list in Workers auth layer.
30	}
31	
32	function buildHandlers(db: Db) {
33	  const svc = sidebarPreferenceService(db);
34	
35	  // server/src/routes/sidebar-preferences.ts:21
36	  const getSidebarPreferencesMe: Handler = async (ctx) => {
37	    const userId = requireBoardUserIdCtx(ctx);
38	    return Response.json(await svc.getCompanyOrder(userId));
39	  };
40	
41	  // server/src/routes/sidebar-preferences.ts:27
42	  const putSidebarPreferencesMe: Handler = async (ctx) => {
43	    const userId = requireBoardUserIdCtx(ctx);
44	    const body = await ctx.json();
45	    const parsed = upsertSidebarOrderPreferenceSchema.parse(body);
46	    return Response.json(await svc.upsertCompanyOrder(userId, parsed.orderedIds));
47	  };
48	
49	  // server/src/routes/sidebar-preferences.ts:33
50	  const getCompanySidebarPreferencesMe: Handler = async (ctx) => {
51	    const companyId = ctx.param("companyId") ?? "";
52	    assertCompanyAccessCtx(ctx, companyId);
53	    const userId = requireBoardUserIdCtx(ctx);
54	    return Response.json(await svc.getProjectOrder(companyId, userId));
55	  };
56	
57	  // server/src/routes/sidebar-preferences.ts:41
58	  const putCompanySidebarPreferencesMe: Handler = async (ctx) => {
59	    const companyId = ctx.param("companyId") ?? "";
60	    assertCompanyAccessCtx(ctx, companyId);
61	    const userId = requireBoardUserIdCtx(ctx);
62	
63	    const body = await ctx.json();
64	    const parsed = upsertSidebarOrderPreferenceSchema.parse(body);
65	    const result = await svc.upsertProjectOrder(companyId, userId, parsed.orderedIds);
66	
67	    // ctx.actor lacks `runId`; log with null runId.
68	    // TODO(cloudflare): thread runId through ActorContext.
69	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
70	    const actorId = ctx.actor!.type === "agent"
71	      ? (ctx.actor!.agentId ?? "unknown-agent")
72	      : (ctx.actor!.userId ?? "board");
73	    await logActivity(db, {
74	      companyId,
75	      actorType,
76	      actorId,
77	      agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
78	      runId: null,
79	      action: "sidebar_preferences.project_order_updated",
80	      entityType: "company",
81	      entityId: companyId,
82	      details: {
83	        userId,
84	        orderedIds: result.orderedIds,
85	      },
86	    });
87	    return Response.json(result);
88	  };
89	
90	  return { getSidebarPreferencesMe, putSidebarPreferencesMe, getCompanySidebarPreferencesMe, putCompanySidebarPreferencesMe };
91	}
92	
93	export function sidebarPreferenceRoutes(db: Db) {
94	  const router = Router();
95	  const {
96	    getSidebarPreferencesMe,
97	    putSidebarPreferencesMe,
98	    getCompanySidebarPreferencesMe,
99	    putCompanySidebarPreferencesMe,
100	  } = buildHandlers(db);
101	
102	  const storageSentinel = new Proxy({} as StorageService, {
103	    get(_target, prop) {
104	      throw new Error(`sidebarPreference handler unexpectedly accessed storage.${String(prop)}`);
105	    },
106	  });
107	  const deps = { db, storage: storageSentinel };
108	
109	  router.get("/sidebar-preferences/me", expressHandler(getSidebarPreferencesMe, deps));
110	  router.put("/sidebar-preferences/me", expressHandler(putSidebarPreferencesMe, deps));
111	  router.get("/companies/:companyId/sidebar-preferences/me", expressHandler(getCompanySidebarPreferencesMe, deps));
112	  router.put("/companies/:companyId/sidebar-preferences/me", expressHandler(putCompanySidebarPreferencesMe, deps));
113	
114	  return router;
115	}
